"""Build the 75-exercise curriculum from the original business-question backlog."""
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent
ORIGINAL = ROOT / 'docs/kirimlaju_business_questions.md'
source = ORIGINAL.read_text(encoding='utf-8')
questions = {int(n): q for n, q in re.findall(r'^(\d+)\. (.+)$', source, re.M)}
assert len(questions) == 55
items = []

def add(n, title, grain, sql, contract, difficulty='Intermediate'):
    topic = next(label for start, end, label in [
        (1,5,'Executive / KPI'),(6,10,'Service Performance'),(11,17,'Route Performance'),
        (18,24,'Customer'),(25,29,'Package & Weight'),(30,35,'SLA & Delivery'),
        (36,42,'Tracking & Operations'),(43,50,'Data Quality Audit'),(51,55,'Dashboard / Management'),
        (56,60,'Tren & Window Functions'),(61,65,'Customer & Cohort'),
        (66,70,'Tracking Lanjutan'),(71,75,'Analitik Lanjutan')]
        if start <= n <= end)
    tables = [t for t in ['customers','routes','shipments','status_history'] if re.search(r'\b'+t+r'\b', sql)]
    items.append({'id':f'KL-{n:02}', 'number':n, 'topic':topic, 'title':title,
        'difficulty':difficulty, 'business_question':questions[n], 'required_tables':tables,
        'analytical_grain':grain, 'expected_output':[],
        'learning_objectives':[topic, 'PostgreSQL', 'Grain dan denominator yang konsisten'],
        'limitations':contract + ' Nilai transaksi bukan profit. Bulatkan rate/persen dan rata-rata ke 2 desimal, kecuali dinyatakan lain. On-time: status delivered, actual_delivery dan estimated_delivery terisi; actual_delivery <= estimated_delivery. Tanggal aktual sebelum pickup diaudit terpisah, bukan dibersihkan diam-diam.',
        'validation_policy':'Nama dan urutan kolom harus sesuai Expected output. Urutan baris diabaikan; duplikat tetap dihitung.',
        'source_question': n if n <= 55 else None,
        '_sql':sql.strip()})

valid = "status='delivered' AND actual_delivery IS NOT NULL AND estimated_delivery IS NOT NULL"
ontime = valid + ' AND actual_delivery <= estimated_delivery'
late = valid + ' AND actual_delivery > estimated_delivery'
service = f"""SELECT service_type, COUNT(*) AS shipments, SUM(total_cost_idr) AS transaction_value_idr,
ROUND(AVG(total_cost_idr),2) AS avg_cost_idr, ROUND(AVG(weight_kg),2) AS avg_weight_kg,
COUNT(*) FILTER (WHERE {valid}) AS eligible_delivered,
COUNT(*) FILTER (WHERE {ontime}) AS on_time,
ROUND(100.0*COUNT(*) FILTER (WHERE {ontime})/NULLIF(COUNT(*) FILTER (WHERE {valid}),0),2) AS on_time_rate_pct,
ROUND(100.0*COUNT(*) FILTER (WHERE status='delivered')/COUNT(*),2) AS delivery_rate_pct,
ROUND(100.0*COUNT(*) FILTER (WHERE status='lost')/COUNT(*),2) AS loss_rate_pct,
ROUND(100.0*COUNT(*) FILTER (WHERE status='returned')/COUNT(*),2) AS return_rate_pct
FROM shipments GROUP BY service_type"""
route = f"""SELECT route_id, COUNT(*) AS shipments, SUM(total_cost_idr) AS transaction_value_idr,
ROUND(AVG(total_cost_idr),2) AS avg_cost_idr,
COUNT(*) FILTER (WHERE {valid}) AS eligible_delivered,
COUNT(*) FILTER (WHERE {ontime}) AS on_time,
COUNT(*) FILTER (WHERE {late}) AS late_deliveries,
COUNT(*) FILTER (WHERE status='lost') AS lost,
COUNT(*) FILTER (WHERE status='returned') AS returned,
ROUND(100.0*COUNT(*) FILTER (WHERE {ontime})/NULLIF(COUNT(*) FILTER (WHERE {valid}),0),2) AS on_time_rate_pct,
ROUND(100.0*COUNT(*) FILTER (WHERE status='lost')/COUNT(*),2) AS loss_rate_pct,
ROUND(100.0*COUNT(*) FILTER (WHERE status='returned')/COUNT(*),2) AS return_rate_pct
FROM shipments GROUP BY route_id"""
monthly = f"""SELECT DATE_TRUNC('month',pickup_date)::date AS pickup_month, COUNT(*) AS shipments,
SUM(total_cost_idr) AS transaction_value_idr,
COUNT(*) FILTER (WHERE {valid}) AS eligible_delivered,
COUNT(*) FILTER (WHERE {ontime}) AS on_time,
ROUND(100.0*COUNT(*) FILTER (WHERE status='delivered')/COUNT(*),2) AS delivery_rate_pct,
ROUND(100.0*COUNT(*) FILTER (WHERE {ontime})/NULLIF(COUNT(*) FILTER (WHERE {valid}),0),2) AS on_time_rate_pct
FROM shipments GROUP BY 1"""

add(1,'Ringkasan KPI pengiriman','Satu baris keseluruhan',"SELECT COUNT(*) AS total_shipments, SUM(total_cost_idr) AS transaction_value_idr, ROUND(AVG(total_cost_idr),2) AS avg_cost_idr, ROUND(AVG(weight_kg),2) AS avg_weight_kg FROM shipments",'Hitung dari shipments tanpa join.', 'Beginner')
add(2,'Komposisi layanan','Satu baris per service_type',"SELECT service_type, COUNT(*) AS shipments, ROUND(100.0*COUNT(*)/SUM(COUNT(*)) OVER (),2) AS shipment_share_pct FROM shipments GROUP BY service_type",'Persentase menggunakan seluruh shipment.', 'Beginner')
add(3,'Peringkat volume dan nilai layanan','Satu baris per layanan',"WITH x AS (SELECT service_type, COUNT(*) AS shipments, SUM(total_cost_idr) AS transaction_value_idr FROM shipments GROUP BY service_type) SELECT *, DENSE_RANK() OVER (ORDER BY shipments DESC) AS volume_rank, DENSE_RANK() OVER (ORDER BY transaction_value_idr DESC) AS value_rank FROM x",'Tampilkan seluruh layanan dengan dua peringkat; ranking ties menggunakan DENSE_RANK.')
add(4,'Delivery, loss, dan return rate','Satu baris keseluruhan',"SELECT COUNT(*) AS total_shipments, COUNT(*) FILTER (WHERE status='delivered') AS delivered, COUNT(*) FILTER (WHERE status='lost') AS lost, COUNT(*) FILTER (WHERE status='returned') AS returned, ROUND(100.0*COUNT(*) FILTER (WHERE status='delivered')/COUNT(*),2) AS delivery_rate_pct, ROUND(100.0*COUNT(*) FILTER (WHERE status='lost')/COUNT(*),2) AS loss_rate_pct, ROUND(100.0*COUNT(*) FILTER (WHERE status='returned')/COUNT(*),2) AS return_rate_pct FROM shipments",'Denominator semua shipment.', 'Beginner')
add(5,'Tren KPI bulanan','Satu baris per bulan pickup',monthly,'Tampilkan bulan yang memiliki shipment; bulan berbentuk tanggal hari pertama.')
add(6,'Profil volume dan nilai layanan','Satu baris per layanan',"SELECT service_type, COUNT(*) AS shipments, SUM(total_cost_idr) AS transaction_value_idr, ROUND(AVG(total_cost_idr),2) AS avg_cost_idr, ROUND(AVG(weight_kg),2) AS avg_weight_kg FROM shipments GROUP BY service_type",'Gunakan nilai service_type persis dari data.', 'Beginner')
add(7,'Layanan dengan SLA terbaik','Satu baris per layanan',f'WITH x AS ({service}) SELECT service_type, eligible_delivered, on_time, on_time_rate_pct, DENSE_RANK() OVER (ORDER BY on_time_rate_pct DESC NULLS LAST) AS sla_rank FROM x','Tampilkan semua layanan, ranking berdasarkan rate yang telah dibulatkan.')
add(8,'Nilai transaksi dan performa delivery','Satu baris per layanan',service,'Bandingkan nilai dan performa melalui scorecard; korelasi sebab-akibat tidak disimpulkan.')
add(9,'Tingkat keterlambatan layanan','Satu baris per layanan',f"SELECT service_type, COUNT(*) FILTER (WHERE {valid}) AS eligible_delivered, COUNT(*) FILTER (WHERE {late}) AS late_deliveries, ROUND(100.0*COUNT(*) FILTER (WHERE {late})/NULLIF(COUNT(*) FILTER (WHERE {valid}),0),2) AS late_rate_pct FROM shipments GROUP BY service_type",'Late rate hanya dari eligible delivered.')
add(10,'Volume tinggi dan outcome buruk','Satu baris per layanan',f"WITH x AS ({service}) SELECT service_type, shipments, delivery_rate_pct, loss_rate_pct, return_rate_pct, shipments >= AVG(shipments) OVER () AS high_volume, delivery_rate_pct < AVG(delivery_rate_pct) OVER () AS below_avg_delivery FROM x",'High volume >= rata-rata volume antar layanan; below average memakai rata-rata tak berbobot dari delivery rate layanan.')
add(11,'Peringkat volume rute','Satu baris per rute aktif',"SELECT route_id, COUNT(*) AS shipments, DENSE_RANK() OVER (ORDER BY COUNT(*) DESC) AS volume_rank FROM shipments GROUP BY route_id",'Tampilkan seluruh rute aktif.', 'Beginner')
add(12,'Peringkat nilai transaksi rute','Satu baris per rute aktif',"SELECT route_id, SUM(total_cost_idr) AS transaction_value_idr, DENSE_RANK() OVER (ORDER BY SUM(total_cost_idr) DESC) AS value_rank FROM shipments GROUP BY route_id",'Tampilkan seluruh rute aktif.')
add(13,'Biaya rata-rata tertinggi dan terendah','Satu baris per rute aktif',"WITH x AS (SELECT route_id, ROUND(AVG(total_cost_idr),2) AS avg_cost_idr FROM shipments GROUP BY route_id) SELECT *, DENSE_RANK() OVER (ORDER BY avg_cost_idr DESC) AS highest_rank, DENSE_RANK() OVER (ORDER BY avg_cost_idr) AS lowest_rank FROM x",'Kedua ranking menggunakan rata-rata yang telah dibulatkan.')
add(14,'Ranking SLA rute','Satu baris per rute aktif',f'WITH x AS ({route}) SELECT route_id, eligible_delivered, on_time, on_time_rate_pct, DENSE_RANK() OVER (ORDER BY on_time_rate_pct DESC NULLS LAST) AS best_rank, DENSE_RANK() OVER (ORDER BY on_time_rate_pct ASC NULLS LAST) AS worst_rank FROM x','Tampilkan semua rute aktif; ranking berdasarkan rate yang dibulatkan.')
add(15,'Korelasi jarak dan durasi','Satu baris keseluruhan',f"SELECT COUNT(*) AS eligible_delivered, ROUND(CORR(r.distance_km::float,(s.actual_delivery-s.pickup_date)::float)::numeric,4) AS distance_duration_corr, ROUND(CORR(r.distance_km::float,(s.actual_delivery-s.estimated_delivery)::float)::numeric,4) AS distance_lateness_corr FROM shipments s JOIN routes r USING(route_id) WHERE {valid}",'Pearson CORR; pembulatan koefisien 4 desimal. Lateness bertanda negatif berarti lebih awal.', 'Advanced')
add(16,'Risiko lost dan returned per rute','Satu baris per rute aktif',f'WITH x AS ({route}) SELECT route_id, shipments, lost, returned, loss_rate_pct, return_rate_pct FROM x','Tampilkan semua rute agar numerator dan denominator dapat ditinjau.')
add(17,'Prioritas investigasi rute','Satu baris per rute aktif',f"WITH x AS ({route}) SELECT route_id, shipments, transaction_value_idr, avg_cost_idr, on_time_rate_pct, loss_rate_pct, return_rate_pct, (on_time_rate_pct < 80 OR loss_rate_pct >= 5 OR return_rate_pct >= 10) AS needs_review FROM x",'Flag evaluasi jika SLA <80%, loss >=5%, atau return >=10%. Ini prioritas investigasi, bukan bukti profit/rugi.')
add(18,'Business versus individual','Satu baris per customer_type',"SELECT c.customer_type, COUNT(*) AS shipments, ROUND(100.0*COUNT(*)/SUM(COUNT(*)) OVER (),2) AS shipment_share_pct FROM shipments s JOIN customers c USING(customer_id) GROUP BY c.customer_type",'Proporsi shipment, bukan proporsi jumlah customer.', 'Beginner')
add(19,'Nilai transaksi per segmen','Satu baris per customer_type',"SELECT c.customer_type, SUM(s.total_cost_idr) AS transaction_value_idr, DENSE_RANK() OVER (ORDER BY SUM(s.total_cost_idr) DESC) AS value_rank FROM shipments s JOIN customers c USING(customer_id) GROUP BY c.customer_type",'Tampilkan semua segmen.')
add(20,'Biaya shipment per segmen','Satu baris per customer_type',"SELECT c.customer_type, COUNT(*) AS shipments, ROUND(AVG(s.total_cost_idr),2) AS avg_cost_idr FROM shipments s JOIN customers c USING(customer_id) GROUP BY c.customer_type",'Rata-rata pada grain shipment.', 'Beginner')
add(21,'Frekuensi shipment pelanggan','Satu baris per customer',"SELECT c.customer_id, c.name, COUNT(s.shipment_id) AS shipments FROM customers c LEFT JOIN shipments s USING(customer_id) GROUP BY c.customer_id,c.name",'Sertakan pelanggan tanpa shipment.', 'Beginner')
add(22,'Sepuluh pelanggan terbesar','Satu baris per top-10 customer',"WITH x AS (SELECT c.customer_id,c.name,COUNT(s.shipment_id) AS shipments,COALESCE(SUM(s.total_cost_idr),0) AS transaction_value_idr FROM customers c LEFT JOIN shipments s USING(customer_id) GROUP BY c.customer_id,c.name) SELECT *,DENSE_RANK() OVER (ORDER BY shipments DESC) AS volume_rank,DENSE_RANK() OVER (ORDER BY transaction_value_idr DESC) AS value_rank FROM x ORDER BY transaction_value_idr DESC,customer_id LIMIT 10",'Ambil tepat 10 pelanggan berdasarkan nilai transaksi DESC, customer_id ASC sebagai tie-breaker; ranking dihitung terhadap semua customer.')
add(23,'Outcome delivery per segmen','Satu baris per customer_type dan status',"SELECT c.customer_type,s.status,COUNT(*) AS shipments,ROUND(100.0*COUNT(*)/SUM(COUNT(*)) OVER (PARTITION BY c.customer_type),2) AS outcome_share_pct FROM shipments s JOIN customers c USING(customer_id) GROUP BY c.customer_type,s.status",'Denominator shipment dalam segmen.')
add(24,'Pola pelanggan volume tinggi','Satu baris per top customer, service, route',"WITH top_customers AS (SELECT customer_id FROM shipments GROUP BY customer_id ORDER BY COUNT(*) DESC,customer_id LIMIT 10) SELECT s.customer_id,s.service_type,s.route_id,COUNT(*) AS shipments FROM shipments s JOIN top_customers t USING(customer_id) GROUP BY s.customer_id,s.service_type,s.route_id",'Pilih tepat 10 pelanggan berdasarkan jumlah shipment DESC, customer_id ASC.')
add(25,'Volume dan nilai jenis paket','Satu baris per package_type',"SELECT package_type,COUNT(*) AS shipments,SUM(total_cost_idr) AS transaction_value_idr FROM shipments GROUP BY package_type",'Gunakan seluruh shipment.', 'Beginner')
add(26,'Distribusi berat paket','Satu baris per package_type',"SELECT package_type,COUNT(*) AS shipments,MIN(weight_kg) AS min_weight_kg,ROUND(PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY weight_kg)::numeric,2) AS p25_weight_kg,ROUND(PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY weight_kg)::numeric,2) AS median_weight_kg,ROUND(PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY weight_kg)::numeric,2) AS p75_weight_kg,MAX(weight_kg) AS max_weight_kg FROM shipments GROUP BY package_type",'Kuartil memakai PERCENTILE_CONT.', 'Advanced')
add(27,'Outlier berat dengan IQR','Satu baris per package_type',"WITH q AS (SELECT package_type,PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY weight_kg) AS q1,PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY weight_kg) AS q3 FROM shipments GROUP BY package_type) SELECT s.package_type,COUNT(*) AS shipments,COUNT(*) FILTER (WHERE s.weight_kg < q.q1-1.5*(q.q3-q.q1) OR s.weight_kg > q.q3+1.5*(q.q3-q.q1)) AS outlier_shipments FROM shipments s JOIN q USING(package_type) GROUP BY s.package_type",'Outlier di luar pagar Tukey 1,5 IQR dalam setiap kategori; tampilkan kategori dengan nol outlier.', 'Advanced')
add(28,'Preferensi layanan menurut paket','Satu baris per package_type dan service_type',"SELECT package_type,service_type,COUNT(*) AS shipments,ROUND(100.0*COUNT(*)/SUM(COUNT(*)) OVER (PARTITION BY package_type),2) AS service_share_pct FROM shipments GROUP BY package_type,service_type",'Tampilkan seluruh kombinasi yang teramati.')
add(29,'Berat, nilai, dan keterlambatan','Satu baris per kelompok berat',f"WITH x AS (SELECT *,CASE WHEN weight_kg < 1 THEN '<1 kg' WHEN weight_kg <= 5 THEN '1-5 kg' ELSE '>5 kg' END AS weight_band FROM shipments) SELECT weight_band,COUNT(*) AS shipments,ROUND(AVG(total_cost_idr),2) AS avg_cost_idr,COUNT(*) FILTER (WHERE {valid}) AS eligible_delivered,COUNT(*) FILTER (WHERE {late}) AS late_deliveries,ROUND(100.0*COUNT(*) FILTER (WHERE {late})/NULLIF(COUNT(*) FILTER (WHERE {valid}),0),2) AS late_rate_pct FROM x GROUP BY weight_band",'Kelompok: <1, 1 sampai 5 inklusif, >5 kg.')
add(30,'SLA on-time per layanan','Satu baris per layanan',f'WITH x AS ({service}) SELECT service_type,eligible_delivered,on_time,on_time_rate_pct FROM x','Tampilkan eligible denominator dan on-time numerator.')
add(31,'Rata-rata dan median keterlambatan','Satu baris keseluruhan',f"SELECT COUNT(*) AS late_deliveries,ROUND(AVG(actual_delivery-estimated_delivery),2) AS avg_late_days,ROUND(PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY actual_delivery-estimated_delivery)::numeric,2) AS median_late_days FROM shipments WHERE {late}",'Hanya eligible delivered yang terlambat.')
add(32,'Keterlambatan route-service','Satu baris per route dan service aktif',f"SELECT route_id,service_type,COUNT(*) FILTER (WHERE {valid}) AS eligible_delivered,COUNT(*) FILTER (WHERE {late}) AS late_deliveries,ROUND(100.0*COUNT(*) FILTER (WHERE {late})/NULLIF(COUNT(*) FILTER (WHERE {valid}),0),2) AS late_rate_pct FROM shipments GROUP BY route_id,service_type",'Tampilkan semua kombinasi aktif, termasuk nol late.')
add(33,'Durasi aktual versus estimasi','Satu baris per layanan',f"SELECT service_type,COUNT(*) AS eligible_delivered,ROUND(AVG(actual_delivery-pickup_date),2) AS avg_actual_days,ROUND(AVG(estimated_delivery-pickup_date),2) AS avg_estimated_days,ROUND(AVG(actual_delivery-estimated_delivery),2) AS avg_delta_days FROM shipments WHERE {valid} GROUP BY service_type",'Perbandingan deskriptif berpasangan pada eligible delivered; bukan uji signifikansi statistik.')
add(34,'Delivered tanpa tanggal aktual','Satu baris keseluruhan',"SELECT COUNT(*) AS delivered_shipments,COUNT(*) FILTER (WHERE actual_delivery IS NULL) AS missing_actual_delivery,ROUND(100.0*COUNT(*) FILTER (WHERE actual_delivery IS NULL)/NULLIF(COUNT(*),0),2) AS missing_rate_pct FROM shipments WHERE status='delivered'",'Denominator hanya status delivered.', 'Beginner')
add(35,'Konflik status dan tracking','Satu baris ringkasan audit',"WITH h AS (SELECT shipment_id,BOOL_OR(status='delivered') AS has_delivered_event FROM status_history GROUP BY shipment_id) SELECT COUNT(*) FILTER (WHERE s.status='delivered' AND s.actual_delivery IS NULL) AS delivered_missing_date,COUNT(*) FILTER (WHERE s.status<>'delivered' AND s.actual_delivery IS NOT NULL) AS non_delivered_with_date,COUNT(*) FILTER (WHERE s.status='delivered' AND NOT COALESCE(h.has_delivered_event,false)) AS delivered_missing_event,COUNT(*) FILTER (WHERE s.status<>'delivered' AND h.has_delivered_event) AS non_delivered_with_event FROM shipments s LEFT JOIN h USING(shipment_id)",'Konflik event berdasarkan keberadaan event delivered, bukan hanya event terakhir.')
add(36,'Jumlah event rata-rata','Satu baris keseluruhan',"WITH x AS (SELECT s.shipment_id,COUNT(h.record_id) AS events FROM shipments s LEFT JOIN status_history h USING(shipment_id) GROUP BY s.shipment_id) SELECT COUNT(*) AS shipments,ROUND(AVG(events),2) AS avg_events_per_shipment FROM x",'Sertakan shipment tanpa histori sebagai nol event.')
add(37,'Frekuensi status event','Satu baris per status event',"SELECT status,COUNT(*) AS events,ROUND(100.0*COUNT(*)/SUM(COUNT(*)) OVER (),2) AS event_share_pct FROM status_history GROUP BY status",'Grain event; denominator semua event.', 'Beginner')
add(38,'Shipment dengan failed delivery','Satu baris keseluruhan',"SELECT COUNT(DISTINCT shipment_id) AS failed_delivery_shipments FROM status_history WHERE status='failed_delivery'",'Hitung shipment unik, bukan jumlah event.', 'Beginner')
add(39,'Frekuensi lokasi tracking','Satu baris per lokasi',"SELECT location,COUNT(*) AS events,COUNT(DISTINCT shipment_id) AS shipments FROM status_history GROUP BY location",'Tampilkan seluruh lokasi termasuk NULL jika ada.', 'Beginner')
add(40,'Transit pickup ke delivered','Satu baris keseluruhan',"WITH x AS (SELECT shipment_id,MIN(update_timestamp) FILTER (WHERE status='pickup_confirmed') AS picked_at,MIN(update_timestamp) FILTER (WHERE status='delivered') AS delivered_at FROM status_history GROUP BY shipment_id) SELECT COUNT(*) AS eligible_shipments,ROUND(AVG(EXTRACT(EPOCH FROM (delivered_at-picked_at))/3600),2) AS avg_transit_hours FROM x WHERE delivered_at>=picked_at",'Pakai event pertama pickup dan delivered, hanya pasangan lengkap dengan durasi nonnegatif.')
add(41,'Pola event shipment bermasalah','Satu baris per urutan event',"WITH x AS (SELECT h.shipment_id,STRING_AGG(h.status,' > ' ORDER BY h.update_timestamp,h.record_id) AS event_sequence FROM status_history h JOIN shipments s USING(shipment_id) WHERE s.status IN ('lost','returned') GROUP BY h.shipment_id) SELECT event_sequence,COUNT(*) AS shipments FROM x GROUP BY event_sequence",'Bermasalah = status shipment lost atau returned. Urut timestamp lalu record_id.', 'Advanced')
add(42,'Audit urutan event','Satu baris ringkasan audit',"WITH e AS (SELECT *,LAG(status) OVER (PARTITION BY shipment_id ORDER BY update_timestamp,record_id) AS previous_status FROM status_history), first_events AS (SELECT DISTINCT ON (shipment_id) shipment_id,status FROM status_history ORDER BY shipment_id,update_timestamp,record_id) SELECT (SELECT COUNT(DISTINCT shipment_id) FROM e WHERE previous_status IN ('delivered','lost','returned_to_sender')) AS shipments_with_event_after_terminal,(SELECT COUNT(*) FROM first_events WHERE status<>'pickup_confirmed') AS shipments_not_starting_with_pickup",'Terminal = delivered, lost, returned_to_sender; event apapun sesudah terminal ditandai. Tie-break record_id.', 'Advanced')
add(43,'Validasi customer dan route','Satu baris ringkasan audit',"SELECT COUNT(*) AS total_shipments,COUNT(*) FILTER (WHERE c.customer_id IS NULL) AS missing_customer,COUNT(*) FILTER (WHERE r.route_id IS NULL) AS missing_route FROM shipments s LEFT JOIN customers c USING(customer_id) LEFT JOIN routes r USING(route_id)",'LEFT JOIN mempertahankan shipment orphan.', 'Beginner')
add(44,'Keunikan tracking number','Satu baris keseluruhan',"SELECT COUNT(*) AS shipments,COUNT(tracking_number) AS non_null_tracking_numbers,COUNT(DISTINCT tracking_number) AS distinct_tracking_numbers,COUNT(tracking_number)-COUNT(DISTINCT tracking_number) AS duplicate_excess FROM shipments",'Duplicate excess = non-null count minus distinct non-null count.', 'Beginner')
add(45,'Missing value setiap kolom','Satu baris per tabel dan kolom',"WITH cells AS (SELECT 'customers' AS table_name,j.key AS column_name,j.value FROM customers t CROSS JOIN LATERAL JSONB_EACH(TO_JSONB(t)) j UNION ALL SELECT 'routes',j.key,j.value FROM routes t CROSS JOIN LATERAL JSONB_EACH(TO_JSONB(t)) j UNION ALL SELECT 'shipments',j.key,j.value FROM shipments t CROSS JOIN LATERAL JSONB_EACH(TO_JSONB(t)) j UNION ALL SELECT 'status_history',j.key,j.value FROM status_history t CROSS JOIN LATERAL JSONB_EACH(TO_JSONB(t)) j) SELECT table_name,column_name,COUNT(*) AS total_rows,COUNT(*) FILTER (WHERE value='null'::jsonb OR value='\"\"'::jsonb) AS missing_values FROM cells GROUP BY table_name,column_name",'Missing = SQL NULL atau string kosong; tampilkan juga kolom tanpa missing.', 'Advanced')
add(46,'Audit tanggal aktual delivered','Satu baris per status',"SELECT status,COUNT(*) AS shipments,COUNT(*) FILTER (WHERE actual_delivery IS NULL) AS missing_actual_delivery FROM shipments GROUP BY status",'Tampilkan semua status untuk membandingkan missing yang wajar dan anomali.', 'Beginner')
add(47,'Audit kewajaran tanggal','Satu baris ringkasan audit',"SELECT COUNT(*) FILTER (WHERE estimated_delivery<pickup_date) AS estimated_before_pickup,COUNT(*) FILTER (WHERE actual_delivery<pickup_date) AS actual_before_pickup,COUNT(*) FILTER (WHERE actual_delivery>estimated_delivery) AS actual_after_estimated,COUNT(*) FILTER (WHERE pickup_date IS NULL OR estimated_delivery IS NULL) AS missing_sla_dates FROM shipments",'Actual sesudah estimasi adalah terlambat, bukan otomatis data tidak valid.')
add(48,'Cakupan histori tracking','Satu baris keseluruhan',"SELECT COUNT(*) AS total_shipments,COUNT(*) FILTER (WHERE EXISTS(SELECT 1 FROM status_history h WHERE h.shipment_id=s.shipment_id)) AS with_tracking,COUNT(*) FILTER (WHERE NOT EXISTS(SELECT 1 FROM status_history h WHERE h.shipment_id=s.shipment_id)) AS without_tracking FROM shipments s",'Satu shipment dihitung sekali walaupun memiliki banyak event.')
add(49,'Audit duplikat dan foreign key','Satu baris per pemeriksaan',"SELECT 'customers_pk_duplicates' AS check_name,COUNT(*)-COUNT(DISTINCT customer_id) AS issue_count FROM customers UNION ALL SELECT 'routes_pk_duplicates',COUNT(*)-COUNT(DISTINCT route_id) FROM routes UNION ALL SELECT 'shipments_pk_duplicates',COUNT(*)-COUNT(DISTINCT shipment_id) FROM shipments UNION ALL SELECT 'history_pk_duplicates',COUNT(*)-COUNT(DISTINCT record_id) FROM status_history UNION ALL SELECT 'shipment_customer_orphans',COUNT(*) FROM shipments s LEFT JOIN customers c USING(customer_id) WHERE c.customer_id IS NULL UNION ALL SELECT 'shipment_route_orphans',COUNT(*) FROM shipments s LEFT JOIN routes r USING(route_id) WHERE r.route_id IS NULL UNION ALL SELECT 'history_shipment_orphans',COUNT(*) FROM status_history h LEFT JOIN shipments s USING(shipment_id) WHERE s.shipment_id IS NULL",'Tujuh pemeriksaan; duplicate = kelebihan baris kunci, bukan duplikat isi non-key.')
add(50,'Dampak missing tanggal pada SLA','Satu baris keseluruhan',f"SELECT COUNT(*) FILTER (WHERE status='delivered') AS delivered_shipments,COUNT(*) FILTER (WHERE {valid}) AS eligible_delivered,COUNT(*) FILTER (WHERE {ontime}) AS on_time,ROUND(100.0*COUNT(*) FILTER (WHERE {ontime})/NULLIF(COUNT(*) FILTER (WHERE {valid}),0),2) AS valid_on_time_rate_pct,ROUND(100.0*COUNT(*) FILTER (WHERE {ontime})/NULLIF(COUNT(*) FILTER (WHERE status='delivered'),0),2) AS naive_on_time_rate_pct FROM shipments",'Bandingkan denominator valid dan naive seluruh delivered. Angka naive hanya untuk audit bias.')
add(51,'Scorecard operations manager','Satu baris per layanan',service,'Outputkan metrik layanan lengkap: volume, value, biaya, berat, SLA, delivery/loss/return.')
add(52,'Outlier multidimensi','Satu baris per kategori dimensi',f"WITH b AS (SELECT s.*,c.customer_type FROM shipments s JOIN customers c USING(customer_id)), dims AS (SELECT b.*,d.dimension,d.dimension_value FROM b CROSS JOIN LATERAL (VALUES ('service',service_type),('route',route_id),('customer_segment',customer_type),('month',TO_CHAR(pickup_date,'YYYY-MM'))) d(dimension,dimension_value)), x AS (SELECT dimension,dimension_value,COUNT(*) AS shipments,ROUND(100.0*COUNT(*) FILTER (WHERE {late})/NULLIF(COUNT(*) FILTER (WHERE {valid}),0),2) AS late_rate_pct FROM dims GROUP BY dimension,dimension_value) SELECT *,DENSE_RANK() OVER (PARTITION BY dimension ORDER BY late_rate_pct DESC NULLS LAST) AS late_rank FROM x",'Tampilkan semua kategori dalam empat dimensi. Outlier dioperasionalkan sebagai ranking late rate, bukan uji statistik.', 'Advanced')
add(53,'Area investigasi operasional','Satu baris per rute yang perlu review',f'WITH x AS ({route}) SELECT route_id,shipments,late_deliveries,lost,returned,on_time_rate_pct FROM x WHERE shipments>=30 AND (on_time_rate_pct<80 OR loss_rate_pct>=5 OR return_rate_pct>=10)','Filter volume >=30 dan setidaknya satu kondisi SLA <80%, loss >=5%, return >=10%.')
add(54,'Prioritas peningkatan on-time','Satu baris per top-10 route-service',f"SELECT route_id,service_type,COUNT(*) FILTER (WHERE {valid}) AS eligible_delivered,COUNT(*) FILTER (WHERE {late}) AS late_deliveries,ROUND(AVG(actual_delivery-estimated_delivery) FILTER (WHERE {late}),2) AS avg_late_days FROM shipments GROUP BY route_id,service_type HAVING COUNT(*) FILTER (WHERE {late})>0 ORDER BY late_deliveries DESC,route_id,service_type LIMIT 10",'Prioritas tepat 10 kombinasi dengan late count terbesar; tie-break route_id, service_type ASC. Ini kandidat investigasi, bukan rekomendasi kausal.')
add(55,'Scorecard layanan per bulan','Satu baris per service dan bulan',f"SELECT DATE_TRUNC('month',pickup_date)::date AS pickup_month,service_type,COUNT(*) AS shipments,SUM(total_cost_idr) AS transaction_value_idr,COUNT(*) FILTER (WHERE {valid}) AS eligible_delivered,COUNT(*) FILTER (WHERE {ontime}) AS on_time,ROUND(100.0*COUNT(*) FILTER (WHERE {ontime})/NULLIF(COUNT(*) FILTER (WHERE {valid}),0),2) AS on_time_rate_pct,ROUND(100.0*COUNT(*) FILTER (WHERE status='lost')/COUNT(*),2) AS loss_rate_pct,ROUND(100.0*COUNT(*) FILTER (WHERE status='returned')/COUNT(*),2) AS return_rate_pct FROM shipments GROUP BY 1,2",'Denominator loss/return semua shipment dalam bulan-layanan; SLA eligible delivered.')

extra = [
'Bagaimana pertumbuhan volume dan nilai transaksi month-over-month?',
'Bagaimana rolling average tiga bulan untuk volume shipment?',
'Berapa nilai transaksi kumulatif per bulan sepanjang periode dataset?',
'Apa tiga rute dengan volume tertinggi pada setiap bulan?',
'Bagaimana volume, late rate, dan nilai transaksi menurut hari pickup?',
'Berapa jumlah pelanggan baru yang melakukan shipment pertama setiap bulan?',
'Bagaimana retensi pelanggan pada bulan berikutnya setelah bulan shipment pertama?',
'Siapa pelanggan tidak aktif selama lebih dari 90 hari relatif terhadap pickup terakhir dataset?',
'Bagaimana kontribusi nilai transaksi pelanggan menurut kelompok desil?',
'Berapa porsi pelanggan yang menggunakan lebih dari satu jenis layanan?',
'Bagaimana transisi antarstatus tracking dan frekuensinya?',
'Berapa rata-rata jeda jam antar-event menurut status asal dan tujuan?',
'Berapa shipment dengan failed delivery yang kemudian memiliki event delivered?',
'Bagaimana kesesuaian status shipment dengan event tracking terakhir?',
'Berapa banyak event tracking dengan timestamp atau lokasi kosong per status?',
'Bagaimana perbandingan tarif transaksi per kg dengan tarif katalog regular dan express?',
'Berapa shipment same_day dengan estimasi delivery berbeda dari tanggal pickup?',
'Bagaimana selisih estimasi durasi shipment dengan estimasi katalog rute untuk regular dan express?',
'Apa lima rute dengan konsentrasi nilai transaksi terbesar di masing-masing layanan?',
'Berapa shipment yang dibutuhkan untuk mencapai target on-time 90% jika shipment tambahan seluruhnya on-time?'
]
questions.update({56+i:q for i,q in enumerate(extra)})
add(56,'Pertumbuhan month-over-month','Satu baris per bulan',f"WITH m AS ({monthly}),x AS (SELECT *,LAG(shipments) OVER (ORDER BY pickup_month) AS previous_shipments,LAG(transaction_value_idr) OVER (ORDER BY pickup_month) AS previous_value_idr FROM m) SELECT pickup_month,shipments,transaction_value_idr,previous_shipments,previous_value_idr,ROUND(100.0*(shipments-previous_shipments)/NULLIF(previous_shipments,0),2) AS volume_growth_pct,ROUND(100.0*(transaction_value_idr-previous_value_idr)/NULLIF(previous_value_idr,0),2) AS value_growth_pct FROM x",'LAG berdasarkan bulan pickup; bulan pertama memiliki growth NULL.', 'Advanced')
add(57,'Rolling average tiga bulan','Satu baris per bulan',f"WITH m AS ({monthly}) SELECT pickup_month,shipments,ROUND(AVG(shipments) OVER (ORDER BY pickup_month ROWS BETWEEN 2 PRECEDING AND CURRENT ROW),2) AS rolling_3_month_avg FROM m",'Jendela sampai 3 bulan teramati; dua bulan pertama memakai jendela parsial.', 'Advanced')
add(58,'Nilai transaksi kumulatif','Satu baris per bulan',f"WITH m AS ({monthly}) SELECT pickup_month,transaction_value_idr,SUM(transaction_value_idr) OVER (ORDER BY pickup_month ROWS UNBOUNDED PRECEDING) AS cumulative_value_idr FROM m",'Kumulatif sepanjang dataset, tidak direset per tahun.')
add(59,'Top tiga rute bulanan','Satu baris per bulan dan rute terpilih',"WITH m AS (SELECT DATE_TRUNC('month',pickup_date)::date AS pickup_month,route_id,COUNT(*) AS shipments FROM shipments GROUP BY 1,2),r AS (SELECT *,ROW_NUMBER() OVER (PARTITION BY pickup_month ORDER BY shipments DESC,route_id) AS route_rank FROM m) SELECT * FROM r WHERE route_rank<=3",'Tepat tiga per bulan; ties diputuskan route_id ASC.', 'Advanced')
add(60,'Pola hari pickup','Satu baris per ISO weekday',f"SELECT EXTRACT(ISODOW FROM pickup_date)::int AS pickup_weekday,COUNT(*) AS shipments,SUM(total_cost_idr) AS transaction_value_idr,COUNT(*) FILTER (WHERE {valid}) AS eligible_delivered,COUNT(*) FILTER (WHERE {late}) AS late_deliveries,ROUND(100.0*COUNT(*) FILTER (WHERE {late})/NULLIF(COUNT(*) FILTER (WHERE {valid}),0),2) AS late_rate_pct FROM shipments GROUP BY 1",'ISO weekday: 1 Senin sampai 7 Minggu.')
add(61,'Pelanggan shipment pertama','Satu baris per bulan pertama aktif',"WITH x AS (SELECT customer_id,MIN(pickup_date) AS first_pickup FROM shipments GROUP BY customer_id) SELECT DATE_TRUNC('month',first_pickup)::date AS first_shipment_month,COUNT(*) AS new_active_customers FROM x GROUP BY 1",'Baru berarti shipment pertama yang teramati, bukan registration_date.')
add(62,'Retensi satu bulan cohort','Satu baris per cohort matang',"WITH active AS (SELECT DISTINCT customer_id,DATE_TRUNC('month',pickup_date)::date AS active_month FROM shipments),cohorts AS (SELECT customer_id,MIN(active_month) AS cohort_month FROM active GROUP BY customer_id) SELECT c.cohort_month,COUNT(*) AS cohort_customers,COUNT(a.customer_id) AS retained_next_month,ROUND(100.0*COUNT(a.customer_id)/COUNT(*),2) AS retention_pct FROM cohorts c LEFT JOIN active a ON a.customer_id=c.customer_id AND a.active_month=(c.cohort_month+INTERVAL '1 month')::date WHERE c.cohort_month<(SELECT MAX(active_month) FROM active) GROUP BY c.cohort_month",'Keluarkan cohort pada bulan terakhir dataset karena observasi bulan berikutnya belum tersedia.', 'Advanced')
add(63,'Pelanggan tidak aktif 90 hari','Satu baris per pelanggan tidak aktif',"WITH x AS (SELECT customer_id,MAX(pickup_date) AS last_pickup FROM shipments GROUP BY customer_id) SELECT customer_id,last_pickup,(SELECT MAX(pickup_date) FROM shipments)-last_pickup AS inactive_days FROM x WHERE (SELECT MAX(pickup_date) FROM shipments)-last_pickup>90",'Hanya pelanggan yang pernah mengirim; anchor adalah MAX(pickup_date), bukan tanggal komputer.')
add(64,'Kontribusi pelanggan per desil','Satu baris per desil',"WITH v AS (SELECT customer_id,SUM(total_cost_idr) AS value_idr FROM shipments GROUP BY customer_id),d AS (SELECT *,NTILE(10) OVER (ORDER BY value_idr DESC,customer_id) AS value_decile FROM v) SELECT value_decile,COUNT(*) AS customers,SUM(value_idr) AS transaction_value_idr,ROUND(100.0*SUM(value_idr)/SUM(SUM(value_idr)) OVER (),2) AS value_share_pct FROM d GROUP BY value_decile",'Desil 1 adalah pelanggan bernilai tertinggi; hanya customer aktif. Ties customer_id ASC.', 'Advanced')
add(65,'Pelanggan multilarayanan','Satu baris keseluruhan',"WITH x AS (SELECT customer_id,COUNT(DISTINCT service_type) AS services FROM shipments GROUP BY customer_id) SELECT COUNT(*) AS active_customers,COUNT(*) FILTER (WHERE services>1) AS multi_service_customers,ROUND(100.0*COUNT(*) FILTER (WHERE services>1)/COUNT(*),2) AS multi_service_pct FROM x",'Denominator seluruh customer yang pernah mengirim.')
add(66,'Frekuensi transisi status','Satu baris per pasangan status',"WITH e AS (SELECT shipment_id,status,LAG(status) OVER (PARTITION BY shipment_id ORDER BY update_timestamp,record_id) AS previous_status FROM status_history) SELECT previous_status,status AS next_status,COUNT(*) AS transitions FROM e WHERE previous_status IS NOT NULL GROUP BY previous_status,status",'Urutan timestamp dan record_id; event pertama tidak punya transisi asal.', 'Advanced')
add(67,'Waktu antarstatus tracking','Satu baris per pasangan status',"WITH e AS (SELECT status,update_timestamp,LAG(status) OVER w AS previous_status,LAG(update_timestamp) OVER w AS previous_timestamp FROM status_history WINDOW w AS (PARTITION BY shipment_id ORDER BY update_timestamp,record_id)) SELECT previous_status,status AS next_status,COUNT(*) AS transitions,ROUND(AVG(EXTRACT(EPOCH FROM(update_timestamp-previous_timestamp))/3600),2) AS avg_gap_hours FROM e WHERE previous_timestamp IS NOT NULL AND update_timestamp IS NOT NULL GROUP BY previous_status,status",'Sertakan jeda nol jam; tidak menghitung event pertama.', 'Advanced')
add(68,'Pemulihan failed delivery','Satu baris keseluruhan',"WITH failed AS (SELECT shipment_id,MIN(update_timestamp) AS first_failed_at FROM status_history WHERE status='failed_delivery' GROUP BY shipment_id) SELECT COUNT(*) AS failed_shipments,COUNT(*) FILTER (WHERE EXISTS(SELECT 1 FROM status_history d WHERE d.shipment_id=f.shipment_id AND d.status='delivered' AND d.update_timestamp>f.first_failed_at)) AS recovered_shipments FROM failed f",'Recovered = delivered timestamp lebih besar daripada timestamp failed pertama, status akhir shipment tidak dipakai.')
add(69,'Kesesuaian status terakhir','Satu baris per status shipment dan latest event',"WITH h AS (SELECT DISTINCT ON (shipment_id) shipment_id,status AS last_event_status FROM status_history ORDER BY shipment_id,update_timestamp DESC NULLS LAST,record_id DESC) SELECT s.status AS shipment_status,h.last_event_status,COUNT(*) AS shipments,CASE WHEN s.status='returned' THEN h.last_event_status='returned_to_sender' ELSE s.status=h.last_event_status END AS status_matches FROM shipments s LEFT JOIN h USING(shipment_id) GROUP BY s.status,h.last_event_status",'Mapping returned ke returned_to_sender; status lain exact match. NULL history menghasilkan NULL match.')
add(70,'Missing data tracking per status','Satu baris per status event',"SELECT status,COUNT(*) AS events,COUNT(*) FILTER (WHERE update_timestamp IS NULL) AS missing_timestamp,COUNT(*) FILTER (WHERE location IS NULL OR location='') AS missing_location FROM status_history GROUP BY status",'Missing lokasi meliputi NULL dan string kosong.', 'Beginner')
add(71,'Tarif aktual versus katalog','Satu baris per regular/express',"WITH x AS (SELECT s.service_type,s.total_cost_idr/s.weight_kg AS actual_price_per_kg,CASE s.service_type WHEN 'regular' THEN r.price_per_kg_regular ELSE r.price_per_kg_express END AS catalog_price_per_kg FROM shipments s JOIN routes r USING(route_id) WHERE s.service_type IN ('regular','express') AND s.weight_kg>0) SELECT service_type,COUNT(*) AS shipments,ROUND(AVG(actual_price_per_kg),2) AS avg_actual_price_per_kg,ROUND(AVG(catalog_price_per_kg),2) AS avg_catalog_price_per_kg,ROUND(AVG(actual_price_per_kg-catalog_price_per_kg),2) AS avg_gap_per_kg FROM x GROUP BY service_type",'Rata-rata sederhana per shipment; bukan weighted average. Gap tidak diasumsikan sebagai kesalahan penagihan.')
add(72,'Estimasi same-day','Satu baris keseluruhan',"SELECT COUNT(*) AS same_day_shipments,COUNT(*) FILTER (WHERE estimated_delivery<>pickup_date) AS estimate_not_same_day,COUNT(*) FILTER (WHERE estimated_delivery IS NULL OR pickup_date IS NULL) AS missing_dates FROM shipments WHERE service_type='same_day'",'Periksa estimasi, bukan actual_delivery; NULL dipisah.', 'Beginner')
add(73,'Durasi estimasi versus katalog','Satu baris per regular/express',"WITH x AS (SELECT s.service_type,s.estimated_delivery-s.pickup_date AS estimated_days,CASE s.service_type WHEN 'regular' THEN r.estimated_days_regular ELSE r.estimated_days_express END AS catalog_days FROM shipments s JOIN routes r USING(route_id) WHERE s.service_type IN ('regular','express') AND s.pickup_date IS NOT NULL AND s.estimated_delivery IS NOT NULL) SELECT service_type,COUNT(*) AS shipments,ROUND(AVG(estimated_days),2) AS avg_estimated_days,ROUND(AVG(catalog_days),2) AS avg_catalog_days,COUNT(*) FILTER (WHERE estimated_days<>catalog_days) AS different_estimates FROM x GROUP BY service_type",'Selisih hari kalender; tidak mengasumsikan hari kerja.')
add(74,'Top lima kontribusi rute per layanan','Satu baris per layanan dan rute terpilih',"WITH x AS (SELECT service_type,route_id,SUM(total_cost_idr) AS transaction_value_idr FROM shipments GROUP BY service_type,route_id),r AS (SELECT *,ROW_NUMBER() OVER (PARTITION BY service_type ORDER BY transaction_value_idr DESC,route_id) AS route_rank,ROUND(100.0*transaction_value_idr/SUM(transaction_value_idr) OVER (PARTITION BY service_type),2) AS service_value_share_pct FROM x) SELECT * FROM r WHERE route_rank<=5",'Tepat lima rute per layanan; share denominator seluruh rute layanan, bukan hanya top 5.', 'Advanced')
add(75,'Target SLA 90 persen','Satu baris per layanan',f"WITH x AS ({service}) SELECT service_type,eligible_delivered,on_time,on_time_rate_pct,GREATEST(0,CEIL((0.90*eligible_delivered-on_time)/0.10))::bigint AS additional_on_time_needed FROM x",'Selesaikan (on_time+x)/(eligible+x)>=0,90; x bilangan bulat nonnegatif. Semua tambahan diasumsikan eligible dan on-time.', 'Advanced')

